    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c]]
    top = min(r for r, c in cells)
    bottom = max(r for r, c in cells)
    left = min(c for r, c in cells)
    right = max(c for r, c in cells)
    color = grid[top][next(c for c in range(w) if grid[top][c])]
    out = [[0] * w for _ in range(h)]
    # Fold the hollow rectangular frame into a triangular fan while keeping
    # the bottom edge as its base.
    for c in range(left, right + 1):
        if grid[top][c]:
            out[top][c - left] = color
    for r in range(top + 1, bottom):
        d = r - top
        if grid[r][left]:
            out[r][min(w - 1, left + d)] = color
        if grid[r][right]:
            out[r][min(w - 1, left + d + right - left)] = color
    for c in range(left, right + 1):
        if grid[bottom][c]:
            out[bottom][c] = color
    return out
